contracts/test/TestAlgebraCallee.sol.content:
// SPDX-License-Identifier: UNLICENSED
pragma solidity =0.8.20;
pragma abicoder v1;

import '../interfaces/IERC20Minimal.sol';

import '../libraries/SafeCast.sol';
import '../libraries/TickMath.sol';

import '../interfaces/callback/IAlgebraMintCallback.sol';
import '../interfaces/callback/IAlgebraSwapCallback.sol';
import '../interfaces/callback/IAlgebraFlashCallback.sol';

import '../interfaces/IAlgebraPool.sol';

import './LiquidityAmounts.sol';

contract TestAlgebraCallee is IAlgebraMintCallback, IAlgebraSwapCallback, IAlgebraFlashCallback {
  using SafeCast for uint256;

  function getPriceAtTick(int24 tick) external pure returns (uint160 sqrtPrice) {
    return TickMath.getSqrtRatioAtTick(tick);
  }

  function swapExact0For1(address pool, uint256 amount0In, address recipient, uint160 limitSqrtPrice) external {
    IAlgebraPool(pool).swap(recipient, true, int256(amount0In), limitSqrtPrice, abi.encode(msg.sender));
  }

  function swapExact0For1SupportingFee(address pool, uint256 amount0In, address recipient, uint160 limitSqrtPrice) external {
    IAlgebraPool(pool).swapWithPaymentInAdvance(msg.sender, recipient, true, int256(amount0In), limitSqrtPrice, abi.encode(msg.sender));
  }

  function swap0ForExact1(address pool, uint256 amount1Out, address recipient, uint160 limitSqrtPrice) external {
    unchecked {
      IAlgebraPool(pool).swap(recipient, true, -amount1Out.toInt256(), limitSqrtPrice, abi.encode(msg.sender));
    }
  }

  function swapExact1For0(address pool, uint256 amount1In, address recipient, uint160 limitSqrtPrice) external {
    IAlgebraPool(pool).swap(recipient, false, int256(amount1In), limitSqrtPrice, abi.encode(msg.sender));
  }

  function swapExact1For0SupportingFee(address pool, uint256 amount1In, address recipient, uint160 limitSqrtPrice) external {
    IAlgebraPool(pool).swapWithPaymentInAdvance(msg.sender, recipient, false, int256(amount1In), limitSqrtPrice, abi.encode(msg.sender));
  }

  function swap1ForExact0(address pool, uint256 amount0Out, address recipient, uint160 limitSqrtPrice) external {
    unchecked {
      IAlgebraPool(pool).swap(recipient, false, -amount0Out.toInt256(), limitSqrtPrice, abi.encode(msg.sender));
    }
  }

  function swapToLowerSqrtPrice(address pool, uint160 price, address recipient) external {
    IAlgebraPool(pool).swap(recipient, true, type(int256).max, price, abi.encode(msg.sender));
  }

  function swapToHigherSqrtPrice(address pool, uint160 price, address recipient) external {
    IAlgebraPool(pool).swap(recipient, false, type(int256).max, price, abi.encode(msg.sender));
  }

  event SwapCallback(int256 amount0Delta, int256 amount1Delta);

  function algebraSwapCallback(int256 amount0Delta, int256 amount1Delta, bytes calldata data) external override {
    unchecked {
      address sender = abi.decode(data, (address));

      emit SwapCallback(amount0Delta, amount1Delta);

      if (amount0Delta > 0) {
        IERC20Minimal(IAlgebraPool(msg.sender).token0()).transferFrom(sender, msg.sender, uint256(amount0Delta));
      } else if (amount1Delta > 0) {
        IERC20Minimal(IAlgebraPool(msg.sender).token1()).transferFrom(sender, msg.sender, uint256(amount1Delta));
      } else {
        // if both are not gt 0, both must be 0.
        assert(amount0Delta == 0 && amount1Delta == 0);
      }
    }
  }

  event MintResult(uint256 amount0Owed, uint256 amount1Owed, uint256 resultLiquidity);

  function mint(
    address pool,
    address recipient,
    int24 bottomTick,
    int24 topTick,
    uint128 amount
  ) external returns (uint256 amount0Owed, uint256 amount1Owed, uint256 resultLiquidity) {
    (amount0Owed, amount1Owed, resultLiquidity) = IAlgebraPool(pool).mint(msg.sender, recipient, bottomTick, topTick, amount, abi.encode(msg.sender));
    emit MintResult(amount0Owed, amount1Owed, resultLiquidity);
  }

  event MintCallback(uint256 amount0Owed, uint256 amount1Owed);

  function algebraMintCallback(uint256 amount0Owed, uint256 amount1Owed, bytes calldata data) external override {
    address sender = abi.decode(data, (address));

    if (amount0Owed > 0) IERC20Minimal(IAlgebraPool(msg.sender).token0()).transferFrom(sender, msg.sender, amount0Owed);
    if (amount1Owed > 0) IERC20Minimal(IAlgebraPool(msg.sender).token1()).transferFrom(sender, msg.sender, amount1Owed);

    emit MintCallback(amount0Owed, amount1Owed);
  }

  event FlashCallback(uint256 fee0, uint256 fee1);

  function flash(address pool, address recipient, uint256 amount0, uint256 amount1, uint256 pay0, uint256 pay1) external {
    IAlgebraPool(pool).flash(recipient, amount0, amount1, abi.encode(msg.sender, pay0, pay1));
  }

  function algebraFlashCallback(uint256 fee0, uint256 fee1, bytes calldata data) external override {
    emit FlashCallback(fee0, fee1);

    (address sender, uint256 pay0, uint256 pay1) = abi.decode(data, (address, uint256, uint256));

    if (pay0 > 0) IERC20Minimal(IAlgebraPool(msg.sender).token0()).transferFrom(sender, msg.sender, pay0);
    if (pay1 > 0) IERC20Minimal(IAlgebraPool(msg.sender).token1()).transferFrom(sender, msg.sender, pay1);
  }

  function getPositionKey(address owner, int24 bottomTick, int24 topTick) private pure returns (bytes32 key) {
    assembly {
      key := or(shl(24, or(shl(24, owner), and(bottomTick, 0xFFFFFF))), and(topTick, 0xFFFFFF))
    }
  }
}

contracts/test/TestAlgebraReentrantCalle.content:
// SPDX-License-Identifier: UNLICENSED
pragma solidity =0.8.20;

import '../libraries/TickMath.sol';

import '../interfaces/callback/IAlgebraSwapCallback.sol';

import '../interfaces/IAlgebraPool.sol';
import '../interfaces/IAlgebraFactory.sol';

contract TestAlgebraReentrantCallee is IAlgebraSwapCallback {
  bytes4 private constant desiredSelector = bytes4(keccak256(bytes('locked()')));

  function swapToReenter(address pool) external {
    unchecked {
      IAlgebraPool(pool).swap(address(0), false, 1, TickMath.MAX_SQRT_RATIO - 1, new bytes(0));
    }
  }

  function algebraSwapCallback(int256, int256, bytes calldata) external override {
    int24 tickSpacing = IAlgebraPool(msg.sender).tickSpacing();

    // try to reenter swap
    try IAlgebraPool(msg.sender).swap(address(0), false, 1, 0, new bytes(0)) {} catch (bytes memory reason) {
      require(bytes4(reason) == desiredSelector);
    }

    // try to reenter swap supporting fee
    try IAlgebraPool(msg.sender).swapWithPaymentInAdvance(address(0), address(0), false, 1, 0, new bytes(0)) {} catch (bytes memory reason) {
      require(bytes4(reason) == desiredSelector);
    }

    // try to reenter mint
    try IAlgebraPool(msg.sender).mint(address(0), address(0), 0, tickSpacing, 100, new bytes(0)) {} catch (bytes memory reason) {
      require(bytes4(reason) == desiredSelector);
    }

    // try to reenter collect
    try IAlgebraPool(msg.sender).collect(address(0), 0, 0, 0, 0) {} catch (bytes memory reason) {
      require(bytes4(reason) == desiredSelector);
    }

    // try to reenter burn
    try IAlgebraPool(msg.sender).burn(0, tickSpacing, 0, new bytes(0)) {} catch (bytes memory reason) {
      require(bytes4(reason) == desiredSelector);
    }

    // try to reenter flash
    try IAlgebraPool(msg.sender).flash(address(0), 0, 0, new bytes(0)) {} catch (bytes memory reason) {
      require(bytes4(reason) == desiredSelector);
    }

    // try to reenter setCommunityFee
    try IAlgebraPool(msg.sender).setCommunityFee(10) {} catch (bytes memory reason) {
      require(bytes4(reason) == desiredSelector);
    }

    // try to reenter setTickSpacing
    try IAlgebraPool(msg.sender).setTickSpacing(20) {} catch (bytes memory reason) {
      require(bytes4(reason) == desiredSelector);
    }

    // try to reenter setPlugin
    try IAlgebraPool(msg.sender).setPlugin(address(this)) {} catch (bytes memory reason) {
      require(bytes4(reason) == desiredSelector);
    }

    // try to reenter setPluginConfig
    try IAlgebraPool(msg.sender).setPluginConfig(1) {} catch (bytes memory reason) {
      require(bytes4(reason) == desiredSelector);
    }

    // try to reenter setFee
    try IAlgebraPool(msg.sender).setFee(120) {} catch (bytes memory reason) {
      require(bytes4(reason) == desiredSelector);
    }

    // try to reenter setCommunityFeeVault
    try IAlgebraPool(msg.sender).setCommunityVault(address(this)) {} catch (bytes memory reason) {
      require(bytes4(reason) == desiredSelector);
    }

    // try to get AMM state
    try IAlgebraPool(msg.sender).safelyGetStateOfAMM() {} catch (bytes memory reason) {
      require(bytes4(reason) == desiredSelector);
    }

    // try to reenter sync
    try IAlgebraPool(msg.sender).sync() {} catch (bytes memory reason) {
      require(bytes4(reason) == desiredSelector);
    }

    // try to reenter skim
    try IAlgebraPool(msg.sender).skim() {} catch (bytes memory reason) {
      require(bytes4(reason) == desiredSelector);
    }

    require(IAlgebraPool(msg.sender).isUnlocked() == false);

    require(false, 'Unable to reenter');
  }

  // factory reentrancy
  address public factory;
  address public tokenA;
  address public tokenB;

  function beforeCreatePoolHook(address, address, address, address, address, bytes calldata data) external returns (address plugin) {
    plugin = address(0);
    _createCustomPool(factory, tokenA, tokenB, data);
  }

  function createCustomPool(address _factory, address _tokenA, address _tokenB, bytes calldata data) external returns (address pool) {
    factory = _factory;
    tokenA = _tokenA;
    tokenB = _tokenB;
    pool = _createCustomPool(_factory, _tokenA, _tokenB, data);
  }

  function _createCustomPool(address _factory, address _tokenA, address _tokenB, bytes calldata data) internal returns (address pool) {
    pool = IAlgebraFactory(_factory).createCustomPool(address(this), msg.sender, _tokenA, _tokenB, data);
  }
}

contracts/test/TestAlgebraRouter.sol.content:
// SPDX-License-Identifier: UNLICENSED
pragma solidity =0.8.20;
pragma abicoder v1;

import '../libraries/SafeCast.sol';
import '../libraries/TickMath.sol';

import '../interfaces/IERC20Minimal.sol';
import '../interfaces/callback/IAlgebraSwapCallback.sol';
import '../interfaces/IAlgebraPool.sol';

contract TestAlgebraRouter is IAlgebraSwapCallback {
  using SafeCast for uint256;

  // flash swaps for an exact amount of token0 in the output pool
  function swapForExact0Multi(address recipient, address poolInput, address poolOutput, uint256 amount0Out) external {
    address[] memory pools = new address[](1);
    pools[0] = poolInput;
    unchecked {
      IAlgebraPool(poolOutput).swap(recipient, false, -amount0Out.toInt256(), TickMath.MAX_SQRT_RATIO - 1, abi.encode(pools, msg.sender));
    }
  }

  // flash swaps for an exact amount of token1 in the output pool
  function swapForExact1Multi(address recipient, address poolInput, address poolOutput, uint256 amount1Out) external {
    address[] memory pools = new address[](1);
    pools[0] = poolInput;
    unchecked {
      IAlgebraPool(poolOutput).swap(recipient, true, -amount1Out.toInt256(), TickMath.MIN_SQRT_RATIO + 1, abi.encode(pools, msg.sender));
    }
  }

  event SwapCallback(int256 amount0Delta, int256 amount1Delta);

  function algebraSwapCallback(int256 amount0Delta, int256 amount1Delta, bytes calldata data) public override {
    emit SwapCallback(amount0Delta, amount1Delta);

    (address[] memory pools, address payer) = abi.decode(data, (address[], address));

    if (pools.length == 1) {
      // get the address and amount of the token that we need to pay
      address tokenToBePaid = amount0Delta > 0 ? IAlgebraPool(msg.sender).token0() : IAlgebraPool(msg.sender).token1();
      int256 amountToBePaid = amount0Delta > 0 ? amount0Delta : amount1Delta;

      bool zeroToOne = tokenToBePaid == IAlgebraPool(pools[0]).token1();
      unchecked {
        IAlgebraPool(pools[0]).swap(
          msg.sender,
          zeroToOne,
          -amountToBePaid,
          zeroToOne ? TickMath.MIN_SQRT_RATIO + 1 : TickMath.MAX_SQRT_RATIO - 1,
          abi.encode(new address[](0), payer)
        );
      }
    } else {
      if (amount0Delta > 0) {
        IERC20Minimal(IAlgebraPool(msg.sender).token0()).transferFrom(payer, msg.sender, uint256(amount0Delta));
      } else {
        IERC20Minimal(IAlgebraPool(msg.sender).token1()).transferFrom(payer, msg.sender, uint256(amount1Delta));
      }
    }
  }
}

